/* model compare */
.mc{padding:0}
.mc-prompt{display:flex;align-items:center;gap:10px;padding:14px 16px;border-bottom:1px solid var(--line);font-size:14px;font-weight:500}
.mc-prompt .ms{color:var(--muted)}
.mc-cols{display:grid;grid-template-columns:1fr 1fr}
.mc-col{display:flex;flex-direction:column;gap:10px;padding:16px;min-height:190px;transition:background-color .3s}
.mc-col+.mc-col{border-left:1px solid var(--line)}
.mc-col.win{background:var(--accent-bg)}
.mc-mh{display:flex;align-items:center;justify-content:space-between}
.mc-mb{display:inline-flex;align-items:center;gap:6px;padding:4px 8px;border:1px solid var(--line);font-size:12.5px;font-weight:600;color:var(--text);transition:border-color .2s}
.mc-mb:hover{border-color:var(--icon-line)}
.mc-mb .ms{font-size:13px;color:var(--muted)}
.mc-out{flex:1;font-size:16px;line-height:1.5;font-weight:600;letter-spacing:-.01em;color:var(--text)}
.mc-meta{display:flex;gap:14px;font-family:var(--mono);font-size:11px;color:var(--muted)}
.mc-meta b{color:var(--text);font-weight:700}
.mc-vote{display:flex;justify-content:center;gap:8px;padding:12px 16px;border-top:1px solid var(--line)}
.mc-vote .btn.on{border-color:var(--accent);color:var(--accent)}

/* model compare: a real model menu */
.mc{position:relative;overflow:visible!important}
.mc-menu{position:absolute;z-index:6;width:230px;padding:4px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 16px 36px -16px rgba(0,0,0,.35);opacity:0;visibility:hidden;transform:translateY(-4px) scale(.98);transform-origin:top left;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s linear .3s}
.mc-menu.show{opacity:1;visibility:visible;transform:none;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s}
.mc-mi{display:flex;align-items:center;gap:10px;width:100%;padding:8px 10px;text-align:left;font-size:13.5px;font-weight:500;color:var(--text);transition:background-color .15s}
.mc-mi:hover:not(:disabled){background:var(--chip)}
.mc-mi:disabled{opacity:.45;cursor:not-allowed}
.mc-mi .d{font-size:12px;font-weight:400;color:var(--muted)}
.mc-mi .ms{margin-left:auto;color:var(--accent);opacity:0}
.mc-mi.sel .ms{opacity:1}
[data-style="soft"] .mc-menu{border-radius:14px;border-color:var(--line)}
[data-style="soft"] .mc-mi{border-radius:9px}

/* ---------- model compare ---------- */
{
  const cols = $('#mc-cols'), MODELS = ['Opus 5.5','Sonnet 5.5','Haiku 4.5'];
  const OUT = {
    'Opus 5.5':['Design that ships, for products that think.', 2.6, 1.9, '$0.012'],
    'Sonnet 5.5':['We design and build the AI products your users keep coming back to.', 1.7, 1.2, '$0.004'],
    'Haiku 4.5':['AI products, designed and shipped fast.', 0.9, 0.5, '$0.001']
  };
  let pick = ['Opus 5.5','Haiku 4.5'], ts = [];
  function render(){
    cols.innerHTML = pick.map((m, i) => `<div class="mc-col" data-i="${i}"><div class="mc-mh"><button class="mc-mb" data-i="${i}">${m}${ic('expand_more','sm')}</button><span class="mono-xs">${i ? 'Right' : 'Left'}</span></div><div class="mc-out" id="mc-out${i}"></div><div class="mc-meta" id="mc-meta${i}"><span>First token <b>…</b></span><span>Total <b>…</b></span><span>Cost <b>…</b></span></div></div>`).join('');
  }
  function run(){
    ts.forEach(clearTimeout); ts = []; render(); $$('.mc-vote .btn').forEach(b => b.classList.remove('on'));
    pick.forEach((m, i) => {
      const [txt, total, first, cost] = OUT[m], out = $('#mc-out' + i), words = txt.split(' ');
      ts.push(setTimeout(() => {
        $(`#mc-meta${i}`).children[0].innerHTML = `First token <b>${first.toFixed(1)}s</b>`;
        words.forEach((w, n) => ts.push(setTimeout(() => { out.textContent = words.slice(0, n + 1).join(' '); if (n % 2 === 0) ambient('c71', 'stream'); }, n * ((total - first) * 1000 / words.length))));
        ts.push(setTimeout(() => { const mt = $(`#mc-meta${i}`).children; mt[1].innerHTML = `Total <b>${total.toFixed(1)}s</b>`; mt[2].innerHTML = `Cost <b>${cost}</b>`; ambient('c71', 'pop'); }, (total - first) * 1000));
      }, first * 1000));
    });
  }
  const mm = document.createElement('div'); mm.className = 'mc-menu'; mm.setAttribute('role', 'listbox'); $('#mc').appendChild(mm); let mside = null;
  const closeM = () => { mm.classList.remove('show'); mside = null; };
  cols.addEventListener('click', e => {
    const b = e.target.closest('.mc-mb'); if (!b) return; const i = +b.dataset.i;
    if (mside === i){ closeM(); return; }
    mside = i;
    mm.innerHTML = MODELS.map(m => `<button class="mc-mi ${m === pick[i] ? 'sel' : ''}" role="option" data-m="${m}" ${m === pick[1 - i] ? 'disabled' : ''}><span><span style="display:block">${m}</span><span class="d">${m === pick[1 - i] ? 'In the other column' : OUT[m][3] + ' per run'}</span></span>${ic('check','sm')}</button>`).join('');
    const r = $('#mc').getBoundingClientRect(), br = b.getBoundingClientRect();
    mm.style.left = (br.left - r.left) + 'px'; mm.style.top = (br.bottom - r.top + 6) + 'px'; mm.classList.add('show'); Sound.play('open');
  });
  mm.addEventListener('click', e => { const it = e.target.closest('.mc-mi'); if (!it || it.disabled) return; pick[mside] = it.dataset.m; closeM(); Sound.play('select'); run(); });
  document.addEventListener('pointerdown', e => { if (mside !== null && !mm.contains(e.target) && !e.target.closest('.mc-mb')) closeM(); });
  $('#mc-vote').addEventListener('click', e => {
    const b = e.target.closest('.btn'); if (!b) return;
    $$('.mc-vote .btn').forEach(x => x.classList.toggle('on', x === b));
    $$('.mc-col', cols).forEach((c, i) => c.classList.toggle('win', b.dataset.v === String(i)));
    Sound.play('done'); showToast(b.dataset.v === 't' ? 'Marked as a tie' : `Vote saved for ${pick[+b.dataset.v]}`);
  });
  $('#mc-run').addEventListener('click', () => { Sound.play('tab'); run(); });
  render(); whenSeen($('#c71'), run);
}
